import sys
from collections import defaultdict, deque

sys.setrecursionlimit(200000)

def main():
    input = sys.stdin.readline
    n, q = map(int, input().split())

    # Building the hierarchy tree
    superior = [0] * (n + 1)
    subordinates = defaultdict(list)

    for i in range(2, n + 1):
        superior[i] = int(input())
        subordinates[superior[i]].append(i)

    def bfs_spread(start):
        visited = [False] * (n + 1)
        order = []
        queue = deque([start])

        while queue:
            current = queue.popleft()
            if not visited[current]:
                visited[current] = True
                order.append(current)
                for sub in sorted(subordinates[current]):
                    if not visited[sub]:
                        queue.append(sub)

        return order

    results = []

    for _ in range(q):
        u, k = map(int, input().split())
        order = bfs_spread(u)
        if k <= len(order):
            results.append(order[k - 1])
        else:
            results.append(-1)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

import sys
from collections import defaultdict

def process_queries(n, q, superiors, queries):
    subordinates = defaultdict(list)
    for i in range(2, n + 1):
        subordinates[superiors[i - 2]].append(i)

    def dfs(node):
        result = [node]
        for subordinate in sorted(subordinates[node]):
            result.extend(dfs(subordinate))
        return result

    command_order = dfs(1)

    results = []
    for u, k in queries:
        start_index = command_order.index(u)
        if start_index + k - 1 < len(command_order):
            results.append(command_order[start_index + k - 1])
        else:
            results.append(-1)

    return results

def main():
    n, q = map(int, input().split())
    superiors = list(map(int, input().split()))
    queries = [tuple(map(int, input().split())) for _ in range(q)]

    results = process_queries(n, q, superiors, queries)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
